import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { AppState } from 'react-native';

import { type Key, isOp } from '@/lib/calculator';

// Generated by scripts/gen-sounds.mjs from the prototype's synthesizer.
const SOURCES = {
  digit: require('../../assets/sounds/key-digit.wav'),
  op: require('../../assets/sounds/key-op.wav'),
  fn: require('../../assets/sounds/key-fn.wav'),
  equals: require('../../assets/sounds/key-equals.wav'),
  clear: require('../../assets/sounds/key-clear.wav'),
  rip: require('../../assets/sounds/rip.wav'),
  print1: require('../../assets/sounds/print-1.wav'),
  print2: require('../../assets/sounds/print-2.wav'),
  print3: require('../../assets/sounds/print-3.wav'),
  print4: require('../../assets/sounds/print-4.wav'),
  print5: require('../../assets/sounds/print-5.wav'),
  print6: require('../../assets/sounds/print-6.wav'),
  print7: require('../../assets/sounds/print-7.wav'),
  print8: require('../../assets/sounds/print-8.wav'),
};
type Sound = keyof typeof SOURCES;

/** One player plus whether it is sitting at the start, ready to fire instantly. */
interface Voice {
  player: AudioPlayer;
  rewound: boolean;
}

/** Fast typing overlaps sounds, so each one gets a few voices used in turn. */
const POOL_SIZE: Partial<Record<Sound, number>> = { digit: 4, op: 2, fn: 2, equals: 3, clear: 2 };
const pools = new Map<Sound, { voices: Voice[]; next: number }>();

let started = false;

const AUDIO_MODE = { playsInSilentMode: false, interruptionMode: 'mixWithOthers' } as const;

/** Creates every player up front so key presses never wait on loading. */
export function initSounds(): void {
  if (started) return;
  started = true;
  // Respect the silent switch (like the web prototype on iPhone) and never pause the user's music.
  setAudioModeAsync(AUDIO_MODE).catch(() => {});
  for (const name of Object.keys(SOURCES) as Sound[]) {
    const voices = Array.from({ length: POOL_SIZE[name] ?? 1 }, () => makeVoice(SOURCES[name]));
    pools.set(name, { voices, next: 0 });
  }
  // Coming back to the app: the audio session may have been reset (calls, other apps, Siri),
  // and players can be left paused mid-sound. Restore the mode and rewind everything.
  AppState.addEventListener('change', (state) => {
    if (state !== 'active') return;
    setAudioModeAsync(AUDIO_MODE).catch(() => {});
    for (const { voices } of pools.values()) for (const v of voices) if (!v.player.playing) rewind(v);
  });
}

function makeVoice(source: number): Voice {
  const player = createAudioPlayer(source, {
    // By default each player deactivates the audio session whenever it pauses or finishes. With
    // 0.1s sounds that toggled the session constantly, and the next sound could be lost while it
    // started up again.
    keepAudioSessionActive: true,
    // Load the whole file before playing, rather than streaming it (in Expo Go it comes through
    // the dev server tunnel).
    downloadFirst: true,
  });
  const v: Voice = { player, rewound: true };
  player.addListener('playbackStatusUpdate', (status) => {
    // Rewind as soon as a sound ends, so the next press can play immediately.
    if (status.didJustFinish) rewind(v);
  });
  return v;
}

function rewind(v: Voice): void {
  v.rewound = false;
  v.player
    .seekTo(0)
    .then(() => (v.rewound = true))
    .catch(() => (v.rewound = true));
}

function play(name: Sound): void {
  const pool = pools.get(name);
  if (!pool) return;
  const n = pool.voices.length;
  // Prefer a loaded voice that is already rewound and idle, starting from the next in turn.
  for (let i = 0; i < n; i++) {
    const v = pool.voices[(pool.next + i) % n];
    if (v.player.isLoaded && v.rewound && !v.player.playing) {
      pool.next = (pool.next + i + 1) % n;
      v.rewound = false;
      v.player.play();
      return;
    }
  }
  // All busy (very fast typing): restart the oldest one from the top.
  const v = pool.voices[pool.next];
  pool.next = (pool.next + 1) % n;
  if (!v.player.isLoaded) return;
  v.rewound = false;
  v.player
    .seekTo(0)
    .then(() => v.player.play())
    .catch(() => {});
}

export function playKey(k: Key): void {
  if (/^[0-9]$/.test(k)) play('digit');
  else if (k === '=') play('equals');
  else if (k === 'AC') play('clear');
  else if (isOp(k)) play('op');
  else play('fn');
}

export const playTap = () => play('fn');
export const playRip = () => play('rip');

/** Plays the printer for a number of lines (1–8) and returns how long the feed takes, in ms. */
export function playPrint(lines: number): number {
  const n = Math.max(1, Math.min(8, lines));
  play(`print${n}` as Sound);
  return n * 150;
}
